import React, { useState, useEffect } from 'react';
import SubAdminTable from './SubAdminTable';
import SubAdminViewModal from './SubAdminViewModal';
import SubAdminCard from './SubAdminCard';

const API_URL = 'https://merimonial-backend.onrender.com';

const SubAdminPage = () => {
  const [viewData, setViewData] = useState(null);
  const [cardKey, setCardKey] = useState(0); // to refresh SubAdminCard after create/delete

  // Refresh SubAdminCard whenever a sub-admin is created or deleted
  const refreshCards = () => setCardKey((prev) => prev + 1);

  return (
    <>
      {/* Stats Cards — re-mounts on cardKey change to re-fetch */}
      <div className="p-4">
        <SubAdminCard key={cardKey} />
      </div>

      <div className="p-4">
        <SubAdminTable
          onView={(admin) => setViewData(admin)}
          onCreatedOrDeleted={refreshCards}
        />
      </div>

      {viewData && (
        <SubAdminViewModal data={viewData} onClose={() => setViewData(null)} />
      )}
    </>
  );
};

export default SubAdminPage;